def is_good_function(f, max_t_to_test, num_samples):
    if f(0) != 0:
        return False

    # Conceptual check for sub-additivity over a sampled range
    # Actual formal verification would require symbolic methods or proof.
    for t_idx in range(1, num_samples + 1):
        t = t_idx * (max_t_to_test / num_samples)
        for s_idx in range(t_idx):
            s = s_idx * (max_t_to_test / num_samples)
            if 0 <= s < t:
                if f(t) > f(t - s) + f(s):
                    return False
    return True

import math

def calculate_alpha_i(t, P_i, J_i):
    if t <= 0:
        return 0 # As per paper, alpha_i(0) = 0
    return math.ceil((t + J_i) / P_i)

def calculate_remain(f_sbf, g_rbf, t, num_samples=100):
    max_diff = -float('inf')
    for i in range(num_samples + 1):
        x = i * (t / num_samples)
        diff = f_sbf(x) - g_rbf(x)
        if diff > max_diff:
            max_diff = diff
    return max_diff

def calculate_RTInverse(f_sbf, f_prime_func, t, epsilon_step=0.001, max_epsilon_search=100):
    # Step 1: Calculate delta_t
    delta_t = 0.0
    current_epsilon = epsilon_step
    while current_epsilon <= max_epsilon_search:
        if f_sbf(t + current_epsilon) == f_sbf(t):
            delta_t = current_epsilon
            current_epsilon += epsilon_step
        else:
            break

    # Step 2: Apply the problematic formula
    # This part is directly from the paper and will always return 0.
    # It is highly likely a typo in the original paper.
    return f_prime_func(t + delta_t) - f_prime_func(t + delta_t)

def calculate_convolution(f_func, g_func, t, num_samples=100):
    min_sum = float('inf')
    for i in range(num_samples + 1):
        s = i * (t / num_samples)
        current_sum = f_func(s) + g_func(t - s)
        if current_sum < min_sum:
            min_sum = current_sum
    return min_sum

def calculate_deconvolution(f_func, g_func, t, num_samples=100, max_u_search=100):
    max_diff = -float('inf')
    for i in range(num_samples + 1):
        u = i * (max_u_search / num_samples)
        current_diff = f_func(t + u) - g_func(u)
        if current_diff > max_diff:
            max_diff = current_diff
    return max_diff

def is_optimal_shaper(sigma_i_candidate, task_i, system_C, all_feasible_shapers_for_ti):
    if not is_feasible_shaping_function(sigma_i_candidate, task_i, system_C, system_C_with_shaper(sigma_i_candidate)):
        return False

    for sigma_i_prime in all_feasible_shapers_for_ti:
        if sigma_i_prime == sigma_i_candidate:
            continue

        # Compare response times for all lower priority tasks
        for task_j in task_i.LP_tasks:
            R_j_sigma_i = calculate_response_time(task_j, system_C_with_shaper(sigma_i_candidate))
            R_j_sigma_i_prime = calculate_response_time(task_j, system_C_with_shaper(sigma_i_prime))

            if R_j_sigma_i > R_j_sigma_i_prime:
                return False # sigma_i_candidate is not better than sigma_i_prime
    return True

def calculate_gamma_i(t, alpha_i_func, D_i):
    return max(0, alpha_i_func(t - D_i))

def is_feasible_shaper_condition(sigma_i_func, task_i, alpha_i_func, D_i, max_t_to_test, num_samples):
    if not is_good_function(sigma_i_func, max_t_to_test, num_samples):
        return False

    gamma_i_func = lambda t: calculate_gamma_i(t, alpha_i_func, D_i)

    for t_idx in range(num_samples + 1):
        t = t_idx * (max_t_to_test / num_samples)
        if sigma_i_func(t) < gamma_i_func(t):
            return False
    return True

def calculate_f_for_shaper(t, B_i, D_i, alpha_i_func, P_i, J_i):
    if 0 <= t <= D_i:
        return B_i * t / D_i
    else:
        return alpha_i_func(t - D_i, P_i, J_i)

def get_specific_feasible_shaper(task_i, epsilon=1e-9):
    alpha_i_func = lambda t_val: calculate_alpha_i(t_val, task_i.P_i, task_i.J_i)
    B_i = alpha_i_func(epsilon) # alpha_i(0+epsilon)

    f_func = lambda t_val: calculate_f_for_shaper(t_val, B_i, task_i.D_i, alpha_i_func, task_i.P_i, task_i.J_i)

    # The feasible shaper is f_deconv_f
    feasible_shaper_func = lambda t_val: calculate_deconvolution(f_func, f_func, t_val)
    return feasible_shaper_func

import math

def calculate_optimal_shaper_periodic_jitter(t, P_i, J_i, D_i):
    B_i = J_i / P_i
    delta_i = min(J_i, D_i)

    if 0 <= t <= delta_i:
        return math.floor(B_i * t)
    else:
        return math.floor((t + J_i - delta_i) / P_i)

def find_optimal_interface(component_C_star, interface_type_params):
    min_sbf_interface = None
    min_bandwidth = float('inf')

    # Iterate through possible interface parameters (e.g., for EDP: Pi, Theta, Delta)
    for params in generate_possible_interface_params(interface_type_params):
        current_interface = create_interface_from_params(params)

        if is_interface_feasible_for_component(current_interface.sbf_func, component_C_star):
            current_bandwidth = calculate_bandwidth(current_interface)
            if current_bandwidth < min_bandwidth:
                min_bandwidth = current_bandwidth
                min_sbf_interface = current_interface

    return min_sbf_interface
